using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// ATMO RDIF (the diff against the reflection parent) is a Reflection object: its parent, image spaces and inorganic
// resources are FormLinks. A whole record from Starfield.esm, both readers, written back byte for byte.
public class AtmosphereReflectionDiffTests
{
    private static void WritesBack(IStarfieldMajorRecordGetter rec, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(w => rec.WriteToBinary(w)));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    // ATMO_VoliiAlpha (00D4BC:Starfield.esm)
    private const string VoliiAlphaHex = "";

    [Fact]
    public void VoliiAlpha()
    {
        foreach (var rec in ReadBoth<IAtmosphereGetter>(Record("ATMO", Hex(VoliiAlphaHex)), f => Atmosphere.CreateFromBinary(f), (s, p) => AtmosphereBinaryOverlay.AtmosphereFactory(s, p)))
        {
            // AtmoBlueGreenBaseMedium01 (050CBD), IS_Atmo_Unique_VoliiAlpha_LUT_Day (13DAC1) and _Night (13DAC2),
            // ResInorgUncommonBenzene_G (0057E7), ResInorgCommonWater_L (0083EC), all Starfield.esm
            rec.ReflectionDiff.ShouldHaveFormIds(0x050CBD, 0x0057E7, 0x0083EC, 0x13DAC1, 0x13DAC2);
            var diff = rec.ReflectionDiff.RootObject();
            diff.IsDiff.ShouldBeTrue();
            diff.Class.Name.ShouldBe("BGSAtmosphere");
            WritesBack(rec, VoliiAlphaHex);
        }
    }

}
